  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "16.50",
      "interpretation": "Acima da MM20 e das EMAs; abaixo de MM50 e MM200 — recuperação de curtíssimo prazo dentro de tendência maior baixista."
    },
    {
      "indicator": "MM20",
      "reading": "15.9880",
      "interpretation": "Suporte dinâmico de curto prazo; preço sustentado acima dele."
    },
    {
      "indicator": "MM50",
      "reading": "16.6160",
      "interpretation": "Resistência imediata — mantém viés de médio prazo mais fraco enquanto estiver acima do preço."
    },
    {
      "indicator": "MM200",
      "reading": "19.3965",
      "interpretation": "Tendência de longo prazo baixista; preço bem abaixo dela."
    },
    {
      "indicator": "EMA9",
      "reading": "15.9606",
      "interpretation": "EMA curta abaixo da EMA21, embora o preço esteja acima de ambas — sinal de recuperação ainda sem cruzamento definitivo."
    },
    {
      "indicator": "EMA21",
      "reading": "16.0945",
      "interpretation": "Suporte de curtíssimo prazo; preço acima, reforçando movimento de recuperação recente."
